<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Event;use Illuminate\Http\Request;use Illuminate\Support\Str;class EventController extends Controller{public function index(){return view('admin.events.index',['items'=>Event::latest('starts_at')->paginate(20)]);}public function create(){return view('admin.events.form',['item'=>new Event]);}public function store(Request $r){Event::create($this->data($r));return redirect()->route('admin.events.index')->with('ok','Событие создано');}public function edit(Event $event){return view('admin.events.form',['item'=>$event]);}public function update(Request $r,Event $event){$event->update($this->data($r));return redirect()->route('admin.events.index')->with('ok','Событие обновлено');}public function destroy(Event $event){$event->delete();return back();}private function data(Request $r):array{$d=$r->validate(['title'=>'required|max:255','description'=>'nullable','place'=>'nullable|max:255','starts_at'=>'required|date','ends_at'=>'nullable|date']);$d['slug']=Str::slug($r->input('slug')?:$d['title']);$d['is_published']=$r->boolean('is_published');return $d;}}